<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import {RouterLink} from 'vue-router';
import {ArrowRight,FileText,Save,Download,Search,Link2,UserRound,Clock,Check,Building2} from '@lucide/vue';
import {api,apiDownload} from '../../lib/api';
import type {ReportRecord,Status} from '../../../shared/types';
import {categoryLabel,companyTypes,statuses,dynamicQuestions} from '../../../shared/catalog';
import {displayDate,displayDateTime,displayValue,messageOf,money} from './helpers';
import AdminState from './AdminState.vue';
import StatusBadge from './StatusBadge.vue';
const props=defineProps<{id:string}>();
const report=ref<ReportRecord|null>(null),loading=ref(true),busy=ref(false),error=ref(''),success=ref(''),status=ref<Status>('new'),note=ref('');
const search=ref(''),matches=ref<ReportRecord[]>([]),matching=ref(false),duplicateOf=ref(''),related=ref<string[]>([]);
const questions=computed(()=>Object.fromEntries(Object.values(dynamicQuestions).flat().filter(Boolean).map(q=>[q!.key,q!.label])));
const flightLabels:Record<string,string>={flightNumber:'מספר טיסה',originAirport:'שדה מוצא',destinationAirport:'שדה יעד',scheduledDeparture:'המראה מתוכננת',actualDeparture:'המראה בפועל',scheduledArrival:'נחיתה מתוכננת',actualArrival:'נחיתה בפועל'};
const amountLabels:Record<string,string>={purchaseAmount:'סכום הרכישה',extraChargeAmount:'חיוב נוסף שנגבה',requestedRefundAmount:'החזר שהתבקש',receivedRefundAmount:'החזר שהתקבל בפועל',additionalClaimedLoss:'נזק נוסף נטען'};
async function load(){loading.value=true;error.value='';try{const result=await api<{report:ReportRecord}>('/api/admin/reports/'+encodeURIComponent(props.id));report.value=result.report;status.value=result.report.status;duplicateOf.value=result.report.duplicateOf||'';related.value=[...result.report.relatedReportIds];}catch(e){error.value=messageOf(e);}finally{loading.value=false;}}
async function update(body:Record<string,unknown>,message:string){busy.value=true;error.value='';success.value='';try{const result=await api<{report:ReportRecord}>('/api/admin/reports/'+encodeURIComponent(props.id),{method:'PATCH',body:JSON.stringify(body)});report.value=result.report;status.value=result.report.status;duplicateOf.value=result.report.duplicateOf||'';related.value=[...result.report.relatedReportIds];if('note'in body)note.value='';success.value=message;}catch(e){error.value=messageOf(e);}finally{busy.value=false;}}
async function findMatches(){matching.value=true;error.value='';try{const result=await api<{reports:ReportRecord[]}>('/api/admin/reports?q='+encodeURIComponent(search.value)+'&pageSize=50');matches.value=result.reports.filter(x=>x.id!==props.id);}catch(e){error.value=messageOf(e);}finally{matching.value=false;}}
async function download(id:string,name:string){error.value='';try{await apiDownload('/api/admin/evidence/'+encodeURIComponent(id),name);}catch(e){error.value=messageOf(e);}}
function linkedTitle(id:string){const match=matches.value.find(x=>x.id===id);return match?.publicReference||id;}
onMounted(load);
</script>
<template><RouterLink class="admin-back-link" to="/admin/reports"><ArrowRight :size="15"/>חזרה לכל הדיווחים</RouterLink><div v-if="error" class="admin-error" role="alert">{{error}}</div><div v-if="success" class="admin-success" role="status"><Check :size="16"/>{{success}}</div><AdminState v-if="loading" loading/>
<template v-else-if="report"><div class="admin-page-heading"><div><span class="admin-eyebrow">פרטי הדיווח</span><h1 dir="ltr" style="text-align:right">{{report.publicReference}}</h1><p>התקבל ב־{{displayDateTime(report.createdAt)}} · עודכן ב־{{displayDateTime(report.updatedAt)}}</p></div><StatusBadge :status="report.status"/></div>
<div class="admin-detail-layout"><div class="admin-detail-main"><section class="admin-panel"><header class="admin-panel-header"><h2><FileText :size="19"/>פרטי האירוע</h2><span class="badge">{{categoryLabel(report.primaryCategory)}}</span></header><div class="admin-panel-body"><div class="admin-report-companies"><div v-for="(company,index) in report.companies" :key="index"><span class="admin-company-initial">{{company.name.charAt(0)}}</span><div><RouterLink :to="{path:'/admin/reports',query:{company:company.name}}">{{company.name}}</RouterLink><small>{{companyTypes.find(x=>x.id===company.companyType)?.label}}<template v-if="company.role"> · {{company.role}}</template></small></div></div></div><div class="admin-report-story"><h3>תיאור האירוע</h3><p>{{report.description}}</p></div><dl class="admin-details-grid"><div v-for="[label,value] in [['תאריך האירוע',displayDate(report.incidentDate)],['קטגוריות נוספות',report.secondaryCategories.map(categoryLabel).join(', ')],['השירות שהובטח',report.expectedService],['מה קרה בפועל',report.actualOutcome],['תאריך ההזמנה',displayDate(report.bookingDate)],['ערוץ ההזמנה',report.bookingChannel==='direct'?'הזמנה ישירה':'דרך מתווך'],['שם המתווך',report.intermediaryName],['מספר הזמנה',report.bookingReference],['מספר נוסעים',report.passengerCount]].filter(([,value])=>value!==undefined&&value!=='')" :key="String(label)" class="admin-data-item"><dt>{{label}}</dt><dd>{{displayValue(value)}}</dd></div></dl></div></section>
<section class="admin-panel"><header class="admin-panel-header"><h2>טיסה ושירות שהוזמן</h2></header><div class="admin-panel-body"><dl class="admin-details-grid"><div v-for="(label,key) in flightLabels" :key="key" class="admin-data-item"><dt>{{label}}</dt><dd dir="auto">{{displayValue(report.flight[key as keyof typeof report.flight])}}</dd></div></dl></div></section>
<section class="admin-panel"><header class="admin-panel-header"><h2>פנייה לחברה ותוצאה</h2></header><div class="admin-panel-body"><dl class="admin-details-grid"><div v-for="[label,value] in [['האם נעשתה פנייה לחברה?',report.companyContacted],['תאריך הפנייה',report.companyContactDate?displayDate(report.companyContactDate):undefined],['תשובת החברה',report.companyResponse],['האם העניין נפתר?',report.resolved],['פירוט התוצאה',report.resolution]]" :key="String(label)" class="admin-data-item"><dt>{{label}}</dt><dd>{{displayValue(value)}}</dd></div></dl></div></section>
<section class="admin-panel"><header class="admin-panel-header"><h2>סכומים שנמסרו בדיווח</h2></header><div class="admin-panel-body"><p class="admin-field-hint">הסכומים הם הצהרת הפונה. סכום ששולם, החזר שהתבקש ונזק נטען מוצגים בנפרד.</p><dl class="admin-details-grid"><div v-for="(label,key) in amountLabels" :key="key" class="admin-data-item"><dt>{{label}}</dt><dd>{{money(report[key as keyof ReportRecord],report.currency)}}</dd></div></dl></div></section>
<section v-if="Object.keys(report.dynamicAnswers).length" class="admin-panel"><header class="admin-panel-header"><h2>תשובות לשאלות האירוע</h2></header><div class="admin-panel-body"><dl class="admin-details-grid"><div v-for="(answer,key) in report.dynamicAnswers" :key="key" class="admin-data-item"><dt>{{questions[key]||key}}</dt><dd>{{displayValue(answer)}}</dd></div></dl></div></section>
<section class="admin-panel"><header class="admin-panel-header"><h2>מסמכים ואסמכתאות <span class="admin-count">{{report.evidence.length}}</span></h2></header><div v-if="report.evidence.length" class="admin-evidence-list"><button v-for="file in report.evidence" :key="file.id" class="admin-evidence evidence-download" @click="download(file.id,file.originalFilename)"><span class="admin-file-icon"><FileText :size="20"/></span><span><strong>{{file.originalFilename}}</strong><small>{{file.fileType}} · {{(file.fileSize/1024).toFixed(1)}} KB · {{displayDate(file.createdAt)}}</small></span><Download :size="18"/></button></div><AdminState v-else title="לא צורפו מסמכים" description="מסמכים זמינים להורדה לצוות מורשה בלבד."/></section>
<section class="admin-panel"><header class="admin-panel-header"><h2><Clock :size="18"/>הערות והיסטוריית טיפול</h2></header><div class="admin-panel-body"><form class="admin-note-form" @submit.prevent="update({note},'ההערה נשמרה בהיסטוריית הטיפול.')"><label class="field"><span class="field-label">הערה פנימית לצוות</span><textarea v-model="note" class="textarea" required maxlength="4000" rows="4" placeholder="תיעוד בדיקה, מידע חסר או המשך טיפול…"/></label><button class="btn btn-primary" :disabled="busy||!note.trim()"><Save :size="15"/>שמירת הערה</button></form><div class="admin-timeline"><div v-for="activity in [...report.activities].reverse()" :key="activity.id"><span class="admin-timeline-dot"/><div><strong>{{activity.activityType}}</strong><time>{{displayDateTime(activity.createdAt)}}</time><p>{{activity.note}}</p><small>{{activity.adminUserId||'מערכת'}}</small></div></div><p v-if="!report.activities.length" class="admin-field-hint">אין עדיין פעולות מתועדות.</p></div></div></section></div>
<aside class="admin-detail-sidebar"><section class="admin-panel"><header class="admin-panel-header"><h2>טיפול בדיווח</h2></header><form class="admin-panel-body" @submit.prevent="update({status},'סטטוס הדיווח עודכן.')"><label class="field"><span class="field-label">סטטוס טיפול</span><select v-model="status" class="select"><option v-for="option in statuses" :key="option.id" :value="option.id">{{option.label}}</option></select></label><button class="btn btn-primary admin-full-width" :disabled="busy||status===report.status"><Save :size="15"/>עדכון הסטטוס</button></form></section>
<section class="admin-panel"><header class="admin-panel-header"><h2><UserRound :size="18"/>פרטי הפונה</h2></header><div class="admin-panel-body"><dl class="admin-details-list"><div v-for="[label,value] in [['שם מלא',report.reporter.fullName],['דוא״ל',report.reporter.email],['טלפון',report.reporter.phone],['הפונה הוא הנוסע?',report.reporter.isPassenger],['קשר לנוסע',report.reporter.relationship]]" :key="String(label)" class="admin-data-item"><dt>{{label}}</dt><dd dir="auto">{{displayValue(value)}}</dd></div></dl></div><div class="admin-consents"><h3>הסכמות שנמסרו</h3><p>פרטיות ואמיתות המידע: {{displayValue(report.consents.privacy)}}</p><p v-if="report.consents.caseContact!==undefined">יצירת קשר לצורך הטיפול בדיווח: {{displayValue(report.consents.caseContact)}}</p><p v-if="report.consents.legalContact!==undefined">יצירת קשר לבדיקה משפטית (נוסח היסטורי): {{displayValue(report.consents.legalContact)}}</p><p>עדכוני הארגון: {{displayValue(report.consents.updates)}}</p></div></section>
<section class="admin-panel"><header class="admin-panel-header"><h2><Link2 :size="18"/>קישור וכפילויות</h2></header><div class="admin-panel-body"><p class="admin-field-hint">חפשו דיווחים קיימים, ובחרו קשר לאחר בדיקה אנושית. הקישור אינו מוחק דיווח.</p><form class="admin-related-search" @submit.prevent="findMatches"><input v-model="search" class="input" aria-label="חיפוש דיווח לקישור" placeholder="מספר דיווח או שם חברה" minlength="2" required/><button class="btn btn-secondary" :disabled="matching" aria-label="חיפוש"><Search :size="16"/></button></form><div v-if="matches.length" class="admin-match-list"><label v-for="match in matches" :key="match.id"><input v-model="related" :value="match.id" type="checkbox"/><span><strong>{{match.publicReference}}</strong><small>{{match.companies.map(x=>x.name).join(', ')}}</small></span></label></div><p v-if="matching" class="admin-field-hint" role="status">מחפשים דיווחים…</p><label class="field"><span class="field-label">כפילות של דיווח</span><select v-model="duplicateOf" class="select"><option value="">ללא סימון כפילות</option><option v-if="report.duplicateOf&&!matches.some(x=>x.id===report?.duplicateOf)" :value="report.duplicateOf">{{report.duplicateOf}}</option><option v-for="match in matches" :key="match.id" :value="match.id">{{match.publicReference}}</option></select></label><div v-if="related.length" class="admin-related-selected"><div v-for="id in related" :key="id"><RouterLink :to="'/admin/reports/'+id" class="admin-report-reference">{{linkedTitle(id)}}</RouterLink><button class="admin-icon-button" :aria-label="'הסרת קשר '+linkedTitle(id)" @click="related=related.filter(x=>x!==id)">×</button></div></div><button class="btn btn-secondary admin-full-width" :disabled="busy" @click="update({duplicateOf:duplicateOf||null,relatedReportIds:related},'קשרי הדיווח עודכנו.')"><Link2 :size="15"/>שמירת קשרים</button></div></section></aside></div></template></template>
